-- 'on' for a non-style option carries the option's OWN citation in the note, from any writer:
-- 'authority: <option> <file> sha256 <64 lowercase hex>'.
ALTER TABLE public.ca_horse_style_switch
  DROP CONSTRAINT IF EXISTS ca_horse_style_switch_on_cites_authority,
  ADD CONSTRAINT ca_horse_style_switch_on_cites_authority CHECK (
    state <> 'on'
    OR option IN (
    -- registry:style-options:begin
    'styleValueBettorNotManiac', 'styleBigBetHonesty', 'styleRaiseRespect',
    'styleTightReRaiserRespect', 'styleFoldRatePreRepair', 'styleValueExtraction', 'styleFoldBluff'
    -- registry:style-options:end
    )
    OR (note IS NOT NULL AND note LIKE 'authority: ' || option || ' %' AND note ~ 'sha256 [0-9a-f]{64}')
  );

-- Shadow and canary only where the engine has a shadow arm: the seven style options. 'on' never for an off-only
-- option (an owner hold, a measured harm, a superseded option), from any writer.
ALTER TABLE public.ca_horse_style_switch
  DROP CONSTRAINT IF EXISTS ca_horse_style_switch_state_fits_option,
  ADD CONSTRAINT ca_horse_style_switch_state_fits_option CHECK (
    state = 'off'
    OR (state = 'on' AND option NOT IN (
    -- registry:off-only-options:begin
    'v16Hu', 'v17RiverProbe', 'v23ShortDeck', 'v24PloDefense', 'v32FacingDefense',
    'v33DepthCeiling', 'v46ShortDeck', 'v55OmahaRiverTripsFlat', 'omahaSmallBlindSteal',
    'omahaBeatenMadeHandDefense', 'omahaBluffCatcherRaiseFold', 'omahaReraisedPotDiscipline',
    'omahaReraisedFoldVsTight', 'omahaOnePairDiscipline', 'plo6TopSetNutRealization',
    'fixedLimitRiverFullBetRead', 'v62RiverBettorPolarity', 'readPostflopFoldRate',
    'omahaNeutralUnknown', 'omahaTightOpponent', 'omahaTightOpponentSteal', 'huBbDefendsToPrice',
    'huBbDefendsUnreadToPrice', 'huOpenerDefendsToPrice', 'huLimpDefendsToPrice',
    'huSmallBlindStealsVsTightBigBlind', 'committedStackPricedIn', 'holdemPersonaPreflop',
    'aofClosingSeatNashCall', 'nashPushFoldIcm', 'facingOpenFullRingZone', 'vs3BetShortStack',
    'omahaCommitZoneThreeBetPriceRelief', 'lightningParticipationOmaha', 'commitUnderPot'
    -- registry:off-only-options:end
    ))
    OR option IN (
    -- registry:style-options:begin
    'styleValueBettorNotManiac', 'styleBigBetHonesty', 'styleRaiseRespect',
    'styleTightReRaiserRespect', 'styleFoldRatePreRepair', 'styleValueExtraction', 'styleFoldBluff'
    -- registry:style-options:end
    ));

-- The states an option may be set to; NULL for an option that is not registered.
CREATE OR REPLACE FUNCTION public.fn_ca_horse_option_switch_states(p_option text)
RETURNS text[]
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, public
AS $function$
  SELECT CASE
    WHEN p_option IN (
    -- registry:style-options:begin
    'styleValueBettorNotManiac', 'styleBigBetHonesty', 'styleRaiseRespect',
    'styleTightReRaiserRespect', 'styleFoldRatePreRepair', 'styleValueExtraction', 'styleFoldBluff'
